-- 0001_init: PocketPress v0.1 schema (all tables from the development plan,
-- section 5). IDs are TEXT UUIDv7 values generated by the application;
-- timestamps are TEXT RFC3339 (UTC) values also set by the application, so
-- none of the timestamp columns below carry a SQL DEFAULT.
--
-- schema_migrations itself is created and managed by the migration runner
-- (internal/store/migrate.go), not by this file.

CREATE TABLE users (
    id             TEXT PRIMARY KEY,
    email          TEXT NOT NULL UNIQUE COLLATE NOCASE,
    password_hash  TEXT NOT NULL,
    name           TEXT NOT NULL,
    role           TEXT NOT NULL CHECK (role IN ('owner', 'editor')),
    avatar         TEXT,
    active         INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0, 1)),
    last_login_at  TEXT,
    created_at     TEXT NOT NULL,
    updated_at     TEXT NOT NULL
);

CREATE TABLE sessions (
    id          TEXT PRIMARY KEY,
    user_id     TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    -- UNIQUE already gives token_hash a covering index, so no separate
    -- CREATE INDEX for it below (see idx_sessions_expires_at instead).
    token_hash  TEXT NOT NULL UNIQUE,
    created_at  TEXT NOT NULL,
    expires_at  TEXT NOT NULL
);

CREATE INDEX idx_sessions_user_id    ON sessions (user_id);
CREATE INDEX idx_sessions_expires_at ON sessions (expires_at);

-- Singleton: application code always reads/writes the row where id = 1.
CREATE TABLE settings (
    id                    INTEGER PRIMARY KEY CHECK (id = 1),
    site_name             TEXT NOT NULL,
    site_url              TEXT NOT NULL,
    admin_title           TEXT NOT NULL DEFAULT 'PocketPress',
    locale                TEXT NOT NULL DEFAULT 'en',
    timezone              TEXT NOT NULL,
    default_author        TEXT REFERENCES users (id) ON DELETE SET NULL,
    cors_origins          TEXT NOT NULL DEFAULT '[]',
    public_api_enabled    INTEGER NOT NULL DEFAULT 1 CHECK (public_api_enabled IN (0, 1)),
    preview_url_template  TEXT,
    webhook_user_agent    TEXT NOT NULL DEFAULT 'PocketPress'
);

CREATE TABLE categories (
    id           TEXT PRIMARY KEY,
    name         TEXT NOT NULL,
    slug         TEXT NOT NULL UNIQUE,
    description  TEXT,
    created_at   TEXT NOT NULL,
    updated_at   TEXT NOT NULL
);

CREATE TABLE tags (
    id          TEXT PRIMARY KEY,
    name        TEXT NOT NULL,
    slug        TEXT NOT NULL UNIQUE,
    created_at  TEXT NOT NULL,
    updated_at  TEXT NOT NULL
);

CREATE TABLE posts (
    id               TEXT PRIMARY KEY,
    title            TEXT NOT NULL,
    slug             TEXT NOT NULL UNIQUE,
    excerpt          TEXT,
    content_json     TEXT NOT NULL DEFAULT '{}',
    content_html     TEXT NOT NULL DEFAULT '',
    content_text     TEXT NOT NULL DEFAULT '',
    cover_image      TEXT,
    status           TEXT NOT NULL DEFAULT 'draft'
                       CHECK (status IN ('draft', 'scheduled', 'published', 'archived')),
    author           TEXT NOT NULL REFERENCES users (id) ON DELETE RESTRICT,
    featured         INTEGER NOT NULL DEFAULT 0 CHECK (featured IN (0, 1)),
    seo_title        TEXT,
    seo_description  TEXT,
    canonical_url    TEXT,
    og_image         TEXT,
    scheduled_for    TEXT,
    published_at     TEXT,
    created_at       TEXT NOT NULL,
    updated_at       TEXT NOT NULL
);

CREATE INDEX idx_posts_status_published_at ON posts (status, published_at);
CREATE INDEX idx_posts_author              ON posts (author);

CREATE TABLE post_categories (
    post_id      TEXT NOT NULL REFERENCES posts (id) ON DELETE CASCADE,
    category_id  TEXT NOT NULL REFERENCES categories (id) ON DELETE CASCADE,
    PRIMARY KEY (post_id, category_id)
);

CREATE INDEX idx_post_categories_category_id ON post_categories (category_id);

CREATE TABLE post_tags (
    post_id  TEXT NOT NULL REFERENCES posts (id) ON DELETE CASCADE,
    tag_id   TEXT NOT NULL REFERENCES tags (id) ON DELETE CASCADE,
    PRIMARY KEY (post_id, tag_id)
);

CREATE INDEX idx_post_tags_tag_id ON post_tags (tag_id);

CREATE TABLE post_revisions (
    id            TEXT PRIMARY KEY,
    post_id       TEXT NOT NULL REFERENCES posts (id) ON DELETE CASCADE,
    title         TEXT NOT NULL,
    excerpt       TEXT,
    content_json  TEXT NOT NULL DEFAULT '{}',
    content_html  TEXT NOT NULL DEFAULT '',
    editor_id     TEXT NOT NULL REFERENCES users (id) ON DELETE RESTRICT,
    created_at    TEXT NOT NULL
);

CREATE INDEX idx_post_revisions_post_id ON post_revisions (post_id);

CREATE TABLE api_keys (
    id            TEXT PRIMARY KEY,
    name          TEXT NOT NULL,
    prefix        TEXT NOT NULL,
    token_hash    TEXT NOT NULL UNIQUE,
    scopes        TEXT NOT NULL DEFAULT '[]',
    expires_at    TEXT,
    last_used_at  TEXT,
    revoked_at    TEXT,
    created_at    TEXT NOT NULL,
    updated_at    TEXT NOT NULL
);

CREATE TABLE webhooks (
    id                TEXT PRIMARY KEY,
    name              TEXT NOT NULL,
    url               TEXT NOT NULL,
    secret_encrypted  TEXT NOT NULL,
    events            TEXT NOT NULL DEFAULT '[]',
    active            INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0, 1)),
    created_at        TEXT NOT NULL,
    updated_at        TEXT NOT NULL
);

CREATE TABLE webhook_deliveries (
    id               TEXT PRIMARY KEY,
    webhook_id       TEXT NOT NULL REFERENCES webhooks (id) ON DELETE CASCADE,
    event            TEXT NOT NULL,
    event_id         TEXT NOT NULL UNIQUE,
    payload          TEXT NOT NULL DEFAULT '{}',
    attempt          INTEGER NOT NULL DEFAULT 1,
    status           TEXT NOT NULL DEFAULT 'pending'
                       CHECK (status IN ('pending', 'success', 'failed')),
    response_code    INTEGER,
    response_body    TEXT,
    next_attempt_at  TEXT,
    delivered_at     TEXT,
    created_at       TEXT NOT NULL
);

CREATE INDEX idx_webhook_deliveries_webhook_status ON webhook_deliveries (webhook_id, status);
